/// <summary>
/// Extension of form ProjJournalTable
/// </summary>
[ExtensionOf(formStr(ProjJournalTable))]
public final class AVAProjJournalTableFrm_Extension
{
}

Method.Source:
/// <summary>
/// Checks if all line descriptions are filled
/// </summary>
public void avaCheckLineDescriptions()
{
    boolean ret = false;
    ProjJournalTrans locProjJournalTrans;

    select firstonly locProjJournalTrans
        where locProjJournalTrans.JournalId == projJournalTable.JournalId
        && locProjJournalTrans.Txt == '';

    if(locProjJournalTrans.RecId != 0)
    {
        throw error("@NDX:NXAProjTxtEmptyError");
    }
}
